import{_ as p,a0 as l,w as o,s as n,ao as h,I as d,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"LFCS 基礎：sed 命令 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 基礎：sed 命令 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 基礎：sed 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 基礎：sed 命令 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170529 LFCS sed Command","title":"LFCS 基礎：sed 命令","tag":"201710","desc":""},"relativePath":"201710/20170529 LFCS sed Command.md","filePath":"[post].md"}'),r={name:"201710/20170529 LFCS sed Command.md"};function c(g,e,k,b,u,f){const i=l("Link");return o(),n("div",null,[e[13]||(e[13]=h(`<h1 id="lfcs-基礎-sed-命令" tabindex="-1">LFCS 基礎：sed 命令 <a class="header-anchor" href="#lfcs-基礎-sed-命令" aria-label="Permalink to “LFCS 基礎：sed 命令”">​</a></h1><p>Linux 基金會認證系統管理員（LFCS）的另一個有用的命令是 “sed”，最初表示“流式編輯器” （Streaming EDitor）。</p><p>“sed” 命令是一個可以將文件作為流進行編輯的編輯器。流式傳輸文件的方法是從另一個命令使用管道（<code>&gt;</code> 或 <code>|</code>）傳遞，或將其直接加載到 “sed” 中。</p><p>該命令的工作方式與其他編輯器相同，只是文件不顯示，也不允許可視化編輯。命令被傳遞給 “sed” 來操縱流。</p><p>用 “sed” 可以做五件基本的事。當然，“sed” 如此強大，還有其他高級的功能，但你只需要集中精力在五件基本的事上。五種功能類型如下：</p><ol><li>搜索</li><li>替換</li><li>刪除</li><li>添加</li><li>改變/變換</li></ol><p>在深入命令參數之前，我們需要看看基本的語法。</p><h3 id="語法" tabindex="-1">語法 <a class="header-anchor" href="#語法" aria-label="Permalink to “語法”">​</a></h3><p>“sed” 命令的語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed [選項] 命令 [要編輯的文件]</span></span></code></pre></div><p>本文將在適當的部分中介紹這些“選項”。“命令”可以是正則表達式的搜索和替換模式。請繼續閲讀了解 “sed” 如何工作的並學習基本命令。正如我之前提到的，“sed” 是一個非常強大的工具，有更多的選項可用，我將在本文中介紹。</p><h3 id="示例文件" tabindex="-1">示例文件 <a class="header-anchor" href="#示例文件" aria-label="Permalink to “示例文件”">​</a></h3><p>如果你打開一個終端，那你可以創建一個用於 “sed” 示例的文件。執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~</span></span>
<span class="line"><span>grep --help &gt;grephelp.txt</span></span></code></pre></div><p>你現在應該在 HOME 文件夾中有一個名為 <code>grephelp.txt</code> 的文件。該文件的內容是 <code>grep</code> 命令的幫助説明。</p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to “搜索”">​</a></h3><p>搜索特定字符串是編輯器的常見功能，在 “sed” 中執行搜索也不例外。</p><p>執行搜索以在文件中查找字符串。我們來看一下基本的搜索。</p><p>如果我們想在示例文件搜索 <code>PATTERN</code> 這個詞，我們將使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n &#39;s/PATTERN/PATTERN/p&#39; grephelp.txt</span></span></code></pre></div><p><strong>注意：</strong> 如果剪切粘貼命令，請確保將單引號替換為鍵盤上的標準單引號。</p><p>參數 <code>-n</code> 用於抑制每行的自動打印（除了用 <code>p</code> 命令指定的行）。默認情況下，流入 “sed” 的每一行將被打印到標準輸出（stdout）。如果你不使用 “-n” 選項運行上述命令，你將看到原始文件的每一行以及匹配的行。</p><p>要搜索的文件名是我們在“示例文件”部分中創建的 “grephelp.txt”。</p><p>剩下的部分是 <code>&#39;s/PATTERN/PATTERN/p&#39;</code> 。這一段基本分為四個部分。第一部分的 <code>s</code> 指定執行替換，或搜索並替換。</p><p>剩下的第二部分和第三部分是模式。第一個是要搜索的模式，最後一個是替換流中匹配字符串的模式。此例中，我們找到字符串 <code>PATTERN</code>，並用 <code>PATTERN</code> 替換。通過查找和替換相同的字符串，我們完全不會更改文件，甚至在屏幕上也一樣。</p><p>最後一個命令是 <code>p</code>。 它指定在替換後打印新行。當然，因為替換的是相同的字符串，所以沒有改變。由於我們使用 <code>-n</code> 參數抑制打印行，所以更改的行將使用 <code>p</code> 命令打印。</p><p>這個完整的命令允許我們執行搜索並查看匹配的結果。</p><h3 id="替換" tabindex="-1">替換 <a class="header-anchor" href="#替換" aria-label="Permalink to “替換”">​</a></h3><p>當搜索特定字符串時，你可能希望用匹配的字符串替換新字符串。用另一個字符串替換是很常見的操作。</p><p>我們可以使用以下命令執行相同的搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n &#39;s/PATTERN/Pattern/p&#39; grephelp.txt</span></span></code></pre></div><p>在這時，字符串 “PATTERN” 變為 “Pattern” 並顯示。如果你使用命令 <code>cat grephelp.txt</code> 查看文件，你會看到該文件沒有更改。該更改僅對屏幕上的輸出進行。你可以使用以下命令將輸出通過管道傳輸到另一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/PATTERN/Pattern/&#39; grephelp.txt &gt; grephelp1.txt</span></span></code></pre></div><p>現在將存在一個名為 <code>grephelp1.txt</code> 的新文件，其中保存了更改的文件。如果 <code>p</code> 作為第四個選項留下，那麼有個問題是被替換的字符串的每一行將在文件中重複兩次。我們也可以刪除 “-n” 參數以允許所有的行打印。</p><p>使用相同字符串替換字符串的另一種方法是使用 <code>&amp;</code> 符號來表示搜索字符串。例如，命令 <code>s/PATTERN/&amp;/p</code> 效果是一樣的。我們可以添加字符串，例如添加 <code>S</code>，可以使用命令 <code>s/PATTERN/&amp;S/p</code>。</p><p>如果我們希望在每一行中只替換某種模式呢？可以指定要替換的匹配項的特定出現。當然，每一行的替換都是一個特定的編號。例如，示例文件上有很多破折號。一些行至少有兩條破折號，所以我們可以用另一個字符代替每一行的第二個破折號。每行用星號 <code>*</code> 替換第二個破折號 <code>-</code> 的命令將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/2&#39; grephelp.txt</span></span></code></pre></div><p>在這裏，我們用最初的 <code>s</code> 來執行替換。字符 <code>-</code> 被替換為 <code>*</code>。<code>2</code> 表示我們想要替換每行上的第二個 <code>-</code>（如果存在）。如果我們忽略了命令 <code>2</code>，則替換第一次出現的破折號。只有第一個破折號而不是每行的破折號都被替換。</p><p>如果要搜索並替換帶有星號的行上的所有破折號，請使用 <code>g</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/g&#39; grephelp.txt</span></span></code></pre></div><p>命令也可以組合。假設你想要替換從第二次開始出現的破折號，命令將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/2g&#39; grephelp.txt</span></span></code></pre></div><p>現在從第二個開始出現的破折號將被星號取代。</p><h3 id="刪除" tabindex="-1">刪除 <a class="header-anchor" href="#刪除" aria-label="Permalink to “刪除”">​</a></h3><p>搜索過程中有很多時候你可能想要完全刪除搜索字符串。</p><p>例如，如果要從文件中刪除所有破折號，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-//g&#39; grephelp.txt</span></span></code></pre></div><p>替換字符串為空白，因此匹配的字符串將被刪除。</p><h3 id="添加" tabindex="-1">添加 <a class="header-anchor" href="#添加" aria-label="Permalink to “添加”">​</a></h3><p>當找到匹配時，你可以添加一行特定的文本，來使這行在瀏覽或打印中突出。</p><p>如果要在匹配後插入新行，那麼使用 <code>a</code> 命令，後面跟上新行的字符串。還包括要匹配的字符串。例如，我們可以找到一個 <code>--</code>，並在匹配的行之後添加一行。新行的字符串將是 <code>double dash before this line</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/--/ a &quot;double dash before this line&quot;&#39; grephelp.txt</span></span></code></pre></div><p>如果要在包含匹配字符串的行之前加上這行，請使用 <code>i</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/--/ i &quot;double dash after this line&quot;&#39; grephelp.txt</span></span></code></pre></div><h3 id="改變-變換" tabindex="-1">改變/變換 <a class="header-anchor" href="#改變-變換" aria-label="Permalink to “改變/變換”">​</a></h3><p>如果需要改變/變換一行，則可以使用命令 <code>c</code>。</p><p>假設我們有個有一些私人信息的文檔，我們需要更改包含特定字符串的行。<code>c</code> 命令將改變整行，而不僅僅是搜索字符串。</p><p>假設我們想要阻止示例文件中包含單詞 <code>PATTERN</code> 的每一行。更改的行將顯示為 <code>This line is Top Secret</code>。命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/PATTERN/ c This line is Top Secret&#39; grephelp.txt</span></span></code></pre></div><p>可以進行更改特定字母的大小寫的轉換。例如，我們可以使用命令 <code>y</code> 將所有小寫 <code>a</code> 更改為大寫 <code>A</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;y/a/A/&#39; grephelp.txt</span></span></code></pre></div><p>可以指定多個字母，如 <code>abdg</code>，如下命令所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;y/abdg/ABDG/&#39; grephelp.txt</span></span></code></pre></div><p>確保第二組字母與第一組字母的順序相同，否則會被替換和轉換。例如，字符串 <code>y/a/D/</code> 將用大寫 <code>D</code> 替換所有小寫的 <code>a</code>。</p><h3 id="就地更改" tabindex="-1">就地更改 <a class="header-anchor" href="#就地更改" aria-label="Permalink to “就地更改”">​</a></h3><p>如果你確實要更改所使用的文件，請使用 <code>-i</code> 選項。</p><p>例如，要將 <code>PATTERN</code> 改為 <code>Pattern</code>，並對文件進行更改，則命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -i &#39;s/PATTERN/Pattern/&#39; grephelp.txt</span></span></code></pre></div><p>現在文件 <code>grephelp.txt</code> 將被更改。<code>-i</code> 選項可以與上述任何命令一起使用來更改原始文件的內容。</p><p>練習這些命令，並確保你理解它們。“sed” 命令非常強大。</p><hr>`,71)),d("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.linux.org/threads/lfcs-sed-command.4561/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.linux.org/threads/lfcs-sed-command.4561/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=s("作者：",-1)),a(i,{href:"https://www.linux.org/threads/lfcs-sed-command.4561/"},{default:t(()=>[...e[2]||(e[2]=[s("Jarret B",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[3]||(e[3]=[s("geekpi",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),d("p",null,[e[10]||(e[10]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const T=p(r,[["render",c]]);export{x as __pageData,T as default};
